Build a complete website for the following brief.

<content_brief>
  <business_name>Raw Goods Heavyweight</business_name>
  <tagline>25oz Unsanforized Selvedge Denim & Indestructible Work Jackets</tagline>
  <business_type>apparel</business_type>
  <layout_archetype>bento</layout_archetype>
  <layout_guidelines>Modern Bento Grid architecture featuring heterogeneous card spans (2x2 hero card, 1x2 metric card, 1x1 feature cards) with gradient borders and subtle lift animations.</layout_guidelines>
  <design_system>
    <primary_color>#ffffff</primary_color>
    <accent_color>#3b82f6</accent_color>
    <font_heading>Space Grotesk</font_heading>
    <font_body>Space Grotesk</font_body>
  </design_system>
  <sections>header, hero, denim_pieces, footer</sections>
  <item name="25oz Beast Selvedge Jean" tag="Kojima Mill" description="The heaviest denim in the world. Solid copper rivets, herringbone pocket bags, and pink selvedge ID." />
  <item name="Type III Chore Coat" tag="18oz Waxed Duck" description="Paraffin waxed shelter tent canvas with blanket lining and solid brass doughnut buttons." />
  <item name="Heavy Slub Flannel Shirt" tag="450 GSM" description="Extra-thick double gauze cotton woven with uneven slub yarns for maximum winter warmth." />
  <item name="Horsehide Engineer Boot" tag="Hand-Welted" description="Horween Chromexcel leather with double leather midsoles and Cat's Paw rubber half soles." />
  <contact>
    <address>124 Kojima Denim St, Kurashiki, Okayama 711-0913</address>
    <phone>+81 86 473 1100</phone>
    <email>workshop@rawgoods.jp</email>
    <hours>Wed–Sun: 11am–6pm JST</hours>
  </contact>
</content_brief>

You will build the site ONE SECTION AT A TIME, adhering strictly to the declared design tokens and custom properties.

FIRST SECTION REQUIRED: Write the Header section: a sticky navigation bar with the business name/logo on the left, navigation links (Home, Heavy Iron Collection, Contact) on the right, plus 'View Denim Drops' CTA button. Files: src/components/Header.tsx + src/components/Header.css

Previous assistant implementation (context only):
<thought>
Header accepted. Now building the Hero section for Raw Goods Heavyweight. The headline will be '25oz Unsanforized Selvedge Denim & Indestructible Work Jackets', followed by 'Woven on vintage Toyoda shuttle looms in Kojima. Stiff, heavy, and built to survive decades of honest workshop wear.'. I will provide clear visual hierarchy, primary/secondary action buttons with 0px styling, and metric highlight pills.
</thought>
<tool_call name="write_site">
<file path="src/components/Hero.tsx">
import React from 'react';
import './Hero.css';

export function Hero() {
  return (
    <section className="rgh-hero" id="hero" aria-label="Raw Goods Heavyweight Overview">
      <div className="rgh-hero__inner">
        <div className="rgh-hero__badge" role="status">
          <span className="rgh-hero__badge-dot" aria-hidden="true" />
          <span>Raw Goods Heavyweight — Apparel</span>
        </div>

        <h1 className="rgh-hero__title">
          25oz Unsanforized Selvedge Denim & Indestructible Work Jackets
        </h1>

        <p className="rgh-hero__subtitle">
          Woven on vintage Toyoda shuttle looms in Kojima. Stiff, heavy, and built to survive decades of honest workshop wear.
        </p>

        <div className="rgh-hero__actions">
          <a href="#denim_pieces" className="rgh-hero__btn-primary">
            View Denim Drops
          </a>
          <a href="#footer" className="rgh-hero__btn-secondary">
            Get in Touch
          </a>
        </div>

        <div className="rgh-hero__metrics" role="group" aria-label="Key Highlights">
          <div className="rgh-hero__metric">
            <span className="rgh-hero__metric-value">100%</span>
            <span className="rgh-hero__metric-label">Verifiable Quality</span>
          </div>
          <div className="rgh-hero__metric">
            <span className="rgh-hero__metric-value">24/7</span>
            <span className="rgh-hero__metric-label">Dedicated Support</span>
          </div>
          <div className="rgh-hero__metric">
            <span className="rgh-hero__metric-value">5.0★</span>
            <span className="rgh-hero__metric-label">Client Rating</span>
          </div>
        </div>
      </div>
    </section>
  );
}
</file>
<file path="src/components/Hero.css">
.rgh-hero {
  position: relative;
  width: 100%;
  padding: 5rem 1.5rem 4rem;
  background: var(--surface-obsidian, var(--color-obsidian, var(--bg-color, #ffffff)));
  overflow: hidden;
}

.rgh-hero__inner {
  max-width: var(--page-max-width, 1140px);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.rgh-hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.95rem;
  background: #3b82f6;
  border: 2px solid #000000;
  border-radius: 0px;
  color: #000000;
  font-size: 0.8125rem;
  font-weight: 500;
  margin-bottom: 1.75rem;
}

.rgh-hero__badge-dot {
  width: 7px;
  height: 7px;
  background: var(--color-iridescent-fade, var(--accent-color, #3b82f6));
  border-radius: 50%;
}

.rgh-hero__title {
  font-family: var(--font-heading, 'Space Grotesk', sans-serif);
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 800;
  color: var(--color-paper, var(--text-color, #ffffff));
  line-height: 1.15;
  letter-spacing: -0.025em;
  max-width: 900px;
  margin-bottom: 1.25rem;
}

.rgh-hero__subtitle {
  font-family: var(--font-body, 'Space Grotesk', sans-serif);
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.72));
  line-height: 1.6;
  max-width: 680px;
  margin-bottom: 2.25rem;
}

.rgh-hero__actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 3.5rem;
}

.rgh-hero__btn-primary {
  display: inline-flex;
  align-items: center;
  padding: 0.85rem 2rem;
  background: var(--color-iridescent-fade, var(--accent-color, #3b82f6));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 0px;
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.rgh-hero__btn-primary:hover {
  opacity: 0.92;
  transform: translateY(-2px);
}

.rgh-hero__btn-secondary {
  display: inline-flex;
  align-items: center;
  padding: 0.85rem 2rem;
  background: #3b82f6;
  color: #000000;
  border: 3px solid #000000;
  border-radius: 0px;
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.rgh-hero__btn-secondary:hover {
  border-color: rgba(255, 255, 255, 0.6);
  background: rgba(255, 255, 255, 0.04);
}

.rgh-hero__metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  width: 100%;
  max-width: 640px;
  padding-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.rgh-hero__metric {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.rgh-hero__metric-value {
  font-family: var(--font-heading, 'Space Grotesk', sans-serif);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-paper, #ffffff);
}

.rgh-hero__metric-label {
  font-size: 0.8125rem;
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.55));
}

@media (max-width: 600px) {
  .rgh-hero__metrics { grid-template-columns: 1fr; gap: 1.25rem; }
}
</file>
</tool_call>

